<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;
Auth::requirePermission('competitors.edit');$pdo=Database::connection();$id=(int)($_GET['id']??$_POST['id']??0);
$stmt=$pdo->prepare('SELECT id,identity_code,display_name,entry_type,solo_competitor_id,photo_url FROM bdc_wdc_identities WHERE id=:id');$stmt->execute(['id'=>$id]);$row=$stmt->fetch();if(!$row){http_response_code(404);exit('WDC competitor not found.');}$error='';$sharedPhoto='';
if((int)($row['solo_competitor_id']??0)>0){try{$shared=$pdo->prepare('SELECT photo_url FROM bdc_competitors WHERE id=:id');$shared->execute(['id'=>(int)$row['solo_competitor_id']]);$sharedPhoto=trim((string)$shared->fetchColumn());}catch(Throwable $ignored){}}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token. Refresh and try again.');$file=$_FILES['photo']??null;if(!$file||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Choose a JPG, PNG or WebP photo.');if((int)($file['size']??0)>8*1024*1024)throw new RuntimeException('Photo must be under 8 MB.');$temporary=(string)($file['tmp_name']??'');$mime='';if(class_exists('finfo'))$mime=(string)(new finfo(FILEINFO_MIME_TYPE))->file($temporary);elseif(function_exists('mime_content_type'))$mime=(string)mime_content_type($temporary);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime]))throw new RuntimeException('Photo must be a valid JPG, PNG or WebP image.');$directory=dirname(__DIR__,2).'/uploads/wdc';if(!is_dir($directory)&&!mkdir($directory,0755,true)&&!is_dir($directory))throw new RuntimeException('Photo upload folder is unavailable.');$filename='wdc-'.$id.'-'.bin2hex(random_bytes(6)).'.'.$types[$mime];if(!move_uploaded_file($temporary,$directory.'/'.$filename))throw new RuntimeException('Photo could not be uploaded.');$photo=url('uploads/wdc/'.$filename);$pdo->prepare('UPDATE bdc_wdc_identities SET photo_url=:photo WHERE id=:id')->execute(['photo'=>$photo,'id'=>$id]);Auth::audit((int)(Auth::user()['id']??0),'wdc_photo_replaced',[],'wdc_identity',$id);header('Location: competitors.php#wdc-'.$id,true,303);exit;}catch(Throwable $exception){$error=$exception->getMessage();}}
