?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Adjust WDC Photo</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"></head><body class="bg-light"><main class="container py-4" style="max-width:700px"><div class="d-flex justify-content-between align-items-center gap-3 mb-3"><div><h1 class="h3 mb-1">Adjust WDC photo</h1><p class="text-muted mb-0"><?=e($row['identity_code'])?> · <?=e($row['display_name'])?></p></div><a class="btn btn-outline-dark" href="competitors.php#wdc-<?=$id?>">Back</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="card border-0 shadow-sm"><div class="card-body"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="id" value="<?=$id?>"><img src="<?=e($photo!==''?$photo:url('public/assets/img/default-competitor.svg'))?>" alt="" style="width:180px;height:220px;object-fit:cover;border-radius:16px" class="mb-3 d-block"><label class="form-label" for="wdcPhoto">Replacement photo</label><input class="form-control" id="wdcPhoto" type="file" name="photo" accept="image/jpeg,image/png,image/webp" required><div class="form-text">Updates this WDC identity only. It never creates or changes a BDC or SDC ID. Maximum 8 MB.</div></div><div class="card-footer bg-white text-end"><button class="btn btn-primary">Upload WDC photo</button></div></form></main></body></html>
